('guichard-dauphin','Sir Guichard Dauphin','Great Master of France; a nobleman of that surname, not the king’s son.','Sir Guichard Dauphin|Guichard Dauphin|Guichard'),
('vaudemont','Vaudemont','A French earl named among the dead at Agincourt.','Vaudemont'),
('beaumont','Beaumont','A French earl named among the dead at Agincourt.','Beaumont'),
('roussi','Roussi','A French earl named among the dead at Agincourt.','Roussi'),
('fauconbridge','Fauconbridge','A French earl named among the dead at Agincourt.','Fauconbridge'),
